import { watchDom } from '../../core/observer';
import { wasApplied, markApplied } from '../../utils/dom';
import { runIconEngine } from '../../utils/icons';

import './dashboard.scss';

const ADMIN_LOGO_URL = '/assets/logo/sidebar-logo.png';

function enhanceAdminBrand() {
    const drawers = document.querySelectorAll('.dashboardDocument .mainDrawer-scrollContainer, .dashboardDocument .mainDrawer .scrollContainer');

    drawers.forEach((drawer) => {
        if (drawer.querySelector('.ptv-admin-brand, .adminDrawerLogo')) return;

        const brand = document.createElement('div');
        const logo = document.createElement('img');

        brand.className = 'ptv-admin-brand';
        logo.src = ADMIN_LOGO_URL;
        logo.alt = 'PiggieTV';
        brand.appendChild(logo);
        drawer.prepend(brand);
    });
}

function enhanceDashboardCards() {
    const cards = document.querySelectorAll(
        '.dashboardDocument .card, .dashboardDocument .paperList, .dashboardDocument .listItem, .dashboardDocument .section'
    );

    cards.forEach((card) => {
        if (wasApplied(card, 'ptvDashboardCard')) return;

        markApplied(card, 'ptvDashboardCard');
        card.classList.add('ptv-dashboard-card');
    });
}

function enhanceDashboardIcons() {
    const targets = document.querySelectorAll(
        '.dashboardDocument a, .dashboardDocument button, .dashboardDocument .listItem'
    );

    targets.forEach((target) => {
        if (wasApplied(target, 'ptvDashboardIcon')) return;

        markApplied(target, 'ptvDashboardIcon');
        target.classList.add('ptv-dashboard-icon-row');
    });

    runIconEngine(document);
}

function runDashboard() {
    enhanceAdminBrand();
    enhanceDashboardCards();
    enhanceDashboardIcons();
}

watchDom(runDashboard);
runDashboard();
